// Intended function: convert compact faction pressures into deterministic high-level actions that other strategic/local systems may accept or reject.
#include "strategy/CivilizationStrategy.hpp"
#include "core/Determinism.hpp"
#include <algorithm>
namespace elysium{void CivilizationStrategy::upsert(CivilizationState s){states_[s.factionId]=std::move(s);}std::vector<StrategicAction>CivilizationStrategy::plan(std::uint64_t tick,std::size_t max)const{std::vector<std::uint64_t>ids;for(auto&[id,_]:states_)ids.push_back(id);std::sort(ids.begin(),ids.end());std::vector<StrategicAction>o;for(auto id:ids){auto&s=states_.at(id);for(auto g:s.goals){if(o.size()>=max)return o;StrategicActionKind k=StrategicActionKind::Scout;switch(g){case StrategicGoal::Expand:k=StrategicActionKind::FoundOutpost;break;case StrategicGoal::Trade:k=StrategicActionKind::SendCaravan;break;case StrategicGoal::Research:k=StrategicActionKind::ResearchProject;break;case StrategicGoal::Fortify:k=StrategicActionKind::BuildDefense;break;case StrategicGoal::Raiding:k=StrategicActionKind::Raid;break;case StrategicGoal::Liberation:k=StrategicActionKind::Claim;break;case StrategicGoal::Explore:k=StrategicActionKind::Scout;break;default:k=StrategicActionKind::Negotiate;break;}float budget=std::max(0.f,s.wealth*.05f+s.population*.01f);o.push_back({mix64(id^mix64(tick)^std::uint64_t(k)),id,0,k,budget,float(1+int(g))});}}return o;}}
